  const R=6378137, D=Math.PI/180;
  const to3857=(lon,lat)=>[ lon*R*D, Math.log(Math.tan((90+lat)*D/2))*R ];
  function url(lon,lat,code){
    const [x,y]=to3857(lon,lat); const h=50; // medio-lado del bbox en metros
    const bbox=[x-h,y-h,x+h,y+h].join(',');
    const p={service:'WMS',version:'1.1.1',request:'GetFeatureInfo',layers:LAYER,query_layers:LAYER,
      styles:'AH_MUESTRA_EAC_14_2022',comuna:code,eac:14,eacano:2022,srs:'EPSG:3857',bbox,
      width:101,height:101,x:50,y:50,info_format:'application/json',feature_count:8};
    return PROXY+'?'+Object.entries(p).map(([k,v])=>k+'='+encodeURIComponent(v)).join('&');
  }
  async function gfi(lon,lat,code){
    for(let t=0;t<3;t++){
      try{ const r=await fetch(url(lon,lat,code),{headers:{'Accept':'application/json'}});
        const txt=await r.text();
        let j=null; try{j=JSON.parse(txt);}catch(e){ return {raw:txt.slice(0,200),err:'noJSON'}; }
        return {j};
      }catch(e){ await sleep(300+300*t); }
    }
    return {err:'fail'};
  }
  // extrae valor/AH de las properties (nombres de campo desconocidos -> heurística)
  function pick(props){
    if(!props) return {};
    const num=v=>{const n=parseFloat(String(v).replace(/[^0-9.]/g,''));return isNaN(n)?null:n;};
    let ah=null,val=null,rango=null;
    for(const k of Object.keys(props)){ const K=k.toUpperCase(), v=props[k];
      if(ah==null && /(COD.*AH|AH.*COD|^AH$|CODIGO|C_AH|AREA_HOM)/.test(K) && /^[A-Z]{2,4}\d/.test(String(v))) ah=v;
      if(val==null && /(VALOR|VUNIT|V_UNIT|MONTO|PRECIO|VAL_M|M2)/.test(K)){ const n=num(v); if(n&&n>1000) val=n; }
      if(rango==null && /(RANGO|SUP)/.test(K)) rango=v;
    }
    // si no matchea nombre, toma el número grande más probable como valor
    if(val==null){ for(const k of Object.keys(props)){ const n=num(props[k]); if(n&&n>10000&&n<1e8){ val=n; break; } } }
    if(ah==null){ for(const k of Object.keys(props)){ const v=String(props[k]); if(/^[A-Z]{2,4}\d{2,3}$/.test(v)){ ah=v; break; } } }
    return {ah,val,rango};
  }
